import csv

ts_id = "aacde83b-cb33-52a4-af23-15f624ca5b6a"
count = 0
samples = []
for row in csv.DictReader(open(VALUES_CSV)):
    if row["timeseries_id"] != ts_id:
        continue
    ts = row["timestamp"]  # e.g. "2018-04-10T07:00:00"
    if not ts.startswith("2018-04-10"):
        continue
    hour = int(ts[11:13])  # e.g. 7
    value = float(row["value"])
    # Outside 08:00–18:00: before 08:00 (hours 0-7) or after 18:00 (hours 19-23)
    if hour < 8 or hour > 18:
        if value > 0:
            count += 1
            samples.append((ts, value))

print(f"Count: {count}")
for s in samples:
    print(s)
